<script setup lang="ts">
import ManagedOutputWorkbench from '../components/ManagedOutputWorkbench.vue'
import { computed,ref,watch } from 'vue'
import { ElMessage } from 'element-plus'
import { Link,DocumentCopy,Download } from '@element-plus/icons-vue'
import { useSystemStore } from '../stores/system'
import { post } from '../api/client'
import type { StrmPreview,StorageDiagnosis } from '../api/types'
const system=useSystemStore(),path=ref(''),pickCode=ref(''),preview=ref<StrmPreview|null>(null),error=ref(''),loading=ref(false),diagnosing=ref(false),diagnosis=ref<StorageDiagnosis|null>(null)
const defaultPath=computed(()=>`${system.status?.allowedRoots[0]??'/115/Media'}/电影/示例电影 (2026)/示例电影.mkv`)
watch([path,pickCode],()=>{preview.value=null;diagnosis.value=null;error.value=''})
async function diagnose(){diagnosing.value=true;error.value='';diagnosis.value=null;try{diagnosis.value=await post<StorageDiagnosis>('/cloudStorage/diagnose',{path:path.value.trim(),pickCode:pickCode.value.trim()})}catch(e){error.value=e instanceof Error?e.message:'文件诊断失败'}finally{diagnosing.value=false}}
async function generate(){loading.value=true;error.value='';preview.value=null;try{preview.value=await post<StrmPreview>('/strm/preview',{path:path.value.trim(),pickCode:pickCode.value.trim()})}catch(e){error.value=e instanceof Error?e.message:'预览失败'}finally{loading.value=false}}
async function copy(){try{await navigator.clipboard.writeText(preview.value?.url??'');ElMessage.success('固定解析链接已复制')}catch{ElMessage.error('浏览器不允许访问剪贴板，请手动复制')}}
function download(){if(!preview.value)return;const url=URL.createObjectURL(new Blob([preview.value.content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=(path.value.split('/').pop()??'media').replace(/\.[^.]+$/,'')+'.strm';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><section class="page-heading"><div><span class="page-kicker">ORGANIZE / 固定链接</span><h1>STRM 固定链接</h1><p>让文件指向解析入口，而不是会过期的 115 播放地址。</p></div><span class="phase-label">固定链接 · 实时解析</span></section><el-alert :title="system.status?.storageConfigured?'CloudDrive2 已配置用于目录和文件管理。播放需115官方授权；输出就绪、Emby可见和完整播放验收是独立阶段。':'先配置CloudDrive2进行目录管理，并完成115官方授权获取动态直链；预览不代表已入库或可播放。'" type="warning" :closable="false" show-icon class="section-gap"/><ManagedOutputWorkbench/><div class="strm-grid"><section class="panel"><div class="panel-title"><h2>生成链接预览</h2><Link aria-hidden="true"/></div><form class="strm-form" @submit.prevent="generate"><label for="cloud-path">CloudDrive2 完整路径 <span>必填</span></label><el-input id="cloud-path" v-model="path" :placeholder="defaultPath" size="large"/><p class="field-hint">允许的根目录：{{system.status?.allowedRoots.join('、')??'正在读取'}}</p><label for="pick-code">115 PickCode <span>可选</span></label><el-input id="pick-code" v-model="pickCode" placeholder="仅填写真实 PickCode；不使用 CloudDrive 文件 ID 代替" size="large"/><p class="field-hint">使用真实云盘路径进行索引与身份核对；没有真实 PickCode 时可以留空，不能猜测或用CloudDrive文件ID替代。</p><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-button native-type="submit" type="primary" size="large" :loading="loading" :disabled="!path.trim()">生成固定链接</el-button><el-button size="large" :loading="diagnosing" :disabled="!path.trim()" @click="diagnose">诊断云端文件</el-button></form></section><section class="panel preview-panel"><div class="panel-title"><h2>STRM 内容</h2><span class="muted">一行 HTTP 链接</span></div><template v-if="preview"><el-input :model-value="preview.url" type="textarea" :rows="8" readonly aria-label="生成的 STRM 固定链接"/><p class="field-hint">{{preview.warning}}</p><div class="preview-actions"><el-button @click="copy"><DocumentCopy aria-hidden="true"/>复制链接</el-button><el-button @click="download"><Download aria-hidden="true"/>下载 STRM</el-button></div></template><div v-else class="empty-state"><Link class="empty-icon" aria-hidden="true"/><h3>填写路径后生成预览</h3><p>中文、空格及特殊字符由后端统一编码。<br>播放专用 Key 不会暴露在前端配置中。</p></div></section></div><section v-if="diagnosis" class="panel"><div class="panel-title"><h2>文件与播放诊断</h2><span class="phase-label">{{diagnosis.playback.mode==='redirect'?'可返回 302':'当前模式不支持（不进行中转）'}}</span></div><dl class="config-list"><div><dt>文件</dt><dd>{{diagnosis.file.name}}</dd></div><div><dt>大小</dt><dd>{{diagnosis.file.size.toLocaleString('zh-CN')}} 字节</dd></div><div><dt>访问条件</dt><dd>{{diagnosis.playback.requiresUserAgent?'需要特定 UA；':'无 UA 限制；'}}{{diagnosis.playback.requiresHeaders?'需要附加请求头':'无附加头要求'}}</dd></div><div><dt>直链有效期</dt><dd>{{diagnosis.playback.expiresAt?new Date(diagnosis.playback.expiresAt).toLocaleString('zh-CN'):'服务未返回有效期'}}</dd></div></dl><p class="field-hint">{{diagnosis.note}}</p></section><section class="note-panel"><strong>播放时的目标链路</strong><p>Emby → 原STRM固定入口 → 校验文件级授权与身份 → 按实际播放器UA获取115官方临时链接 → 302直达115 CDN。CloudDrive2用于文件管理；本服务不提供视频中转、HLS或转码兜底。</p><code>{{system.status?.strmEndpoint??'/api/v1/cloudStorage/strm302'}}</code></section></template>
